import {uploadFile} from './upload.js';
export function createConversationUI({api,endpoint,getState,esc,toast,refresh,openDialog,closeDialog}){
 const $=s=>document.querySelector(s);let companyId='',thread='',threads=[],data={messages:[],events:[],jobs:[]},profiles=[],draft='',mode='execute',attachments=[],approvedMedia=false,submitting=false,currentView='',loading=false,loadSequence=0,selectionVersion=0,loadedThread='',preview='',timer,signature='',pendingSubmission=null;
 const approvedImage=()=>attachments.length===1&&getState().assets.find(a=>a.id===attachments[0])?.mime?.startsWith('image/');
 const threadPending=()=>!!thread&&loadedThread!==thread;
 const active=()=>data.jobs.some(j=>['queued','working'].includes(j.state));
 const glyph='<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M24 4v40M4 24h40M10 10l28 28M10 38l28-28" stroke="currentColor" stroke-width="1.5"/><circle cx="43" cy="5" r="3" fill="#ff571f"/></svg>';
 const symbols={instagram:'ig',whatsapp:'wa',google:'G',higgsfield:'hf'};

 const operationLabels={requested:'Pedido registrado',understanding:'Entendendo o objetivo',planning:'Planejamento',producing:'Produção',reviewing:'Revisão',awaiting_approval:'Aguardando aprovação',ready:'Pronta para execução',scheduled:'Agendada',executing:'Executando',verifying:'Verificando resultado',completed:'Concluída',measuring:'Acompanhando resultados',learned:'Aprendizado registrado',blocked:'Bloqueada',uncertain:'Resultado incerto',failed:'Falhou',cancelled:'Cancelada',todo:'A fazer',doing:'Em andamento',done:'Concluída',approved:'Aprovado',pending:'Pendente',working:'Em andamento',verified:'Verificado',recorded:'Registro local',succeeded:'Confirmado'};
 const opLabel=value=>operationLabels[value]||value||'Pendente';
 const evidenceUrl=value=>/^https?:\/\//i.test(value||'')?value:'';
 function operationCards(){return [...(data.operations||[])].sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,3).map(op=>{const plan=op.plan||[],done=plan.filter(step=>['completed','done','succeeded'].includes(step.status)).length,deliveries=(op.artifactIds||[]).map(id=>getState().records.content.find(c=>c.id===id)).filter(Boolean),terminal=['completed','learned','cancelled'].includes(op.state);return `<article class="operation-context" data-operation-id="${esc(op.id)}"><div class="operation-context-heading"><span>OPERAÇÃO DA ${esc(getState().company.name)}</span><span class="badge badge-${esc(op.state)}">${esc(op.paused?'Pausada':opLabel(op.state))}</span></div><h2>${esc(op.objective)}</h2>${plan.length?`<p class="operation-progress">${done} de ${plan.length} etapas concluídas${op.competencies?.length?' · '+esc(op.competencies.map(c=>c.name).join(', ')):''}</p>`:''}${(op.blockers||[]).map(b=>`<p class="operation-blocker">${esc(b.message)}</p>`).join('')}${op.state==='uncertain'?'<p class="operation-blocker">O resultado precisa ser verificado no canal. Esta ação não será repetida automaticamente.</p>':''}${deliveries.length?`<div class="operation-deliveries">${deliveries.map(c=>`<button type="button" data-action="content-detail" data-id="${esc(c.id)}">↗ ${esc(c.title)}</button>`).join('')}</div>`:''}${op.result?.summary?`<p class="operation-result">${esc(op.result.summary)}</p>`:''}${op.result?.measurement?`<p class="operation-result">${esc(op.result.measurement)}</p>`:''}<details class="operation-details"><summary>Plano e registros</summary><ol>${plan.map(step=>`<li><span>${esc(step.title)}</span><small>${esc(opLabel(step.status))}${step.competency?' · '+esc(op.competencies?.find(c=>c.id===step.competency)?.name||step.competency):''}</small></li>`).join('')}</ol>${(op.evidence||[]).length?`<div class="operation-evidence">${op.evidence.map(ev=>`<p><strong>${esc(opLabel(ev.status))}</strong> · ${esc(ev.executor||'Ferramenta')}${ev.channel?' · '+esc(ev.channel):''}<small>${esc(ev.message||ev.error||'Registro da execução')}${ev.externalId?' · '+esc(ev.externalId):''}${ev.occurredAt?' · '+new Date(ev.occurredAt).toLocaleString('pt-BR'):''}</small>${evidenceUrl(ev.url)?`<a href="${esc(ev.url)}" target="_blank" rel="noopener">Ver evidência ↗</a>`:''}</p>`).join('')}</div>`:'<p class="micro-copy">Nenhuma execução externa comprovada nesta operação.</p>'}<div class="operation-links"><a href="#/studio">Estúdio</a><a href="#/tasks">Tarefas</a>${op.campaignId?'<a href="#/campaigns">Campanha</a>':''}<a href="#/results">Resultados</a></div></details><div class="operation-controls">${op.firstInstagram&&op.state==='uncertain'?`<button class="p-button secondary" data-action="link-publication" data-id="${esc(op.id)}">Vincular publicação encontrada</button>`:''}${op.state==='uncertain'?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="verify">Conferir resultado</button>`:''}${op.state==='completed'?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="measure">Acompanhar resultados</button>`:''}${op.state==='measuring'?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="learn">Registrar aprendizado</button>`:''}${op.state==='awaiting_approval'&&!op.paused?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="approve">Aprovar entregas</button>`:''}${!op.firstInstagram&&deliveries.length>0&&op.state==='ready'&&!op.paused?`<button class="p-button secondary" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="execute">Executar publicação</button><a class="quiet-button" href="#/calendar">Agendar</a>`:''}${op.firstInstagram&&!op.paused&&['blocked','ready','reviewing','awaiting_approval','failed'].includes(op.state)?`<button class="p-button secondary" data-action="select-operation-asset" data-id="${esc(op.id)}">Selecionar mídia aprovada</button>`:''}${op.firstInstagram&&!op.paused&&!['executing','verifying','uncertain','completed','measuring','learned','cancelled'].includes(op.state)?`<button class="p-button secondary" data-action="publication-review" data-id="${esc(op.id)}">Revisar publicação</button>`:''}${!terminal&&op.state!=='uncertain'?(op.paused||['blocked','failed'].includes(op.state)?`<button class="quiet-button" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="resume">Retomar operação</button>`:`<button class="quiet-button" data-chat="operation-action" data-id="${esc(op.id)}" data-operation-action="pause">Pausar operação</button>`):''}</div></article>`;}).join('');}

 function ensureCompany(){const id=getState()?.company.id||'';if(companyId!==id){companyId=id;clearThread();threads=[];profiles=[];preview='';}}
 function clearThread(id=''){++selectionVersion;++loadSequence;loading=false;thread=id;loadedThread='';data={messages:[],events:[],jobs:[]};draft='';attachments=[];approvedMedia=false;signature='';pendingSubmission=null;}
 function validateAttachments(ids){
  if(ids.length>6)throw new Error('Adicione até seis referências por mensagem.');
  let bytes=0;for(const id of ids){const asset=getState().assets.find(a=>a.id===id);if(!asset)throw new Error('Uma referência não está disponível nesta empresa.');if(asset.mime?.startsWith('image/')||asset.mime==='application/pdf')bytes+=asset.size||0;}
  if(bytes>20*1024*1024)throw new Error('Use até 20 MB de imagens e PDFs por pedido.');
 }
 function astraStatus(s){const brain=s.integrations.find(c=>c.id==='openai'),ready=brain?.configured&&brain.verifiedAt&&brain.validation?.status==='validated';return '<div class="astra-state"><a class="astra-connection" href="#/integrations"><span class="astra-dot '+(ready?'is-ready':'')+'"></span>'+esc(brain?.values?.agentModel==='gpt-6-astra'||!brain?.values?.agentModel?'GPT-6 Astra':brain.values.agentModel)+' · '+(ready?'conectado':brain?.configured?'validar conexão':'conectar')+'</a><a class="astra-routine" href="#/settings">'+(s.company.policy?.enabled?(s.worker?.running?'Rotina diária ativa':'Rotina aguardando executor'):'Sob demanda')+'</a></div>';}
 function attention(s){const p=s.production?.find(p=>p.blockers?.length);if(!p)return '';return '<details class="chat-attention"><summary>Uma criação precisa de um ajuste para continuar</summary><p>'+esc(p.blockers[0].message)+'</p><button class="quiet-button" data-action="studio-production" data-id="'+esc(p.contentId)+'">Ver o que falta ↗</button></details>';}
 function chat(){ensureCompany();const s=getState();return `<section class="conversation-page ${data.messages.length?'has-messages':''}">${astraStatus(s)}<div class="conversation-toolbar"><button class="quiet-button" data-chat="history">Conversas <span>${threads.length||''}</span></button><button class="quiet-button" data-chat="new">+ Nova conversa</button><a class="quiet-button" href="#/company">Minha empresa ↗</a></div>${!data.messages.length?`<div class="conversation-welcome"><div class="helpu-intelligence">${glyph}</div><span class="intelligence-label">HELPU</span><h1>O que vamos fazer pela sua marca?</h1><p>Converse, envie seus arquivos e acompanhe o Astra cuidando dos próximos passos.</p></div>`:`<div class="conversation-thread-head"><h1>${esc(threads.find(t=>t.id===thread)?.title||'Sua conversa com a Helpu')}</h1></div><div class="chat-transcript" aria-live="polite">${data.messages.map(m=>`<article class="chat-message ${m.role}"><div class="message-byline">${m.role==='user'?'Você':'Helpu'}<time>${new Date(m.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</time></div><div class="chat-message-text">${esc(m.text)}</div>${m.attachments.length?`<span class="chat-file-label">${m.attachments.length} arquivo(s) da biblioteca</span>`:''}</article>`).join('')}${data.jobs[0]?.error?`<div class="chat-run-error">${esc(data.jobs[0].error)}</div>`:''}${active()?`<div class="chat-working"><span class="thinking-dot"></span><span>${esc(data.events.at(-1)?.label||'Organizando os próximos passos…')}</span><button data-chat="stop">Pausar</button></div>`:''}${data.events.length?`<details class="execution-trail"><summary>Ver ${data.events.length} registros da execução</summary><ol>${data.events.slice(-30).map(e=>`<li class="event-${e.kind}"><span>${e.kind==='completed'?'✓':e.kind==='attention'?'!':'·'}</span><div>${esc(e.label)}${e.detail?.confirmation?`<small>${esc(e.detail.confirmation)}</small>`:''}${e.detail?.url?`<small>${esc(e.detail.url)}</small>`:''}</div></li>`).join('')}</ol></details>`:''}</div>`}${operationCards()}${attention(s)}<form id="conversation-composer" class="conversation-composer"><label class="sr-only" for="conversation-prompt">Converse com a Helpu</label><textarea id="conversation-prompt" placeholder="Peça uma criação, organize a semana ou envie um arquivo…" rows="3" required maxlength="16000">${esc(draft)}</textarea>${attachments.length?`<div class="chat-attachments">${attachments.map(id=>`<button type="button" data-chat="remove-attachment" data-id="${id}">${esc(s.assets.find(a=>a.id===id)?.name||'Arquivo')} ×</button>`).join('')}</div>`:''}${approvedImage()?`<label class="approved-media-choice"><input id="conversation-approved-media" type="checkbox" ${approvedMedia?'checked':''}><span>Confirmo que esta é a mídia aprovada para a publicação.<small>A publicação ainda exige a revisão da conta e da legenda e sua aprovação final.</small></span></label>`:''}<div class="composer-controls"><button type="button" class="attach-button" data-chat="attach"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m8 14 7-7a2 2 0 0 1 3 3l-9 9a4 4 0 0 1-6-6L14 2a6 6 0 0 1 8 8L11 21"/></svg>Adicionar arquivo</button><div><label class="composer-mode"><span class="sr-only">Modo da conversa</span><select id="conversation-mode"><option value="execute" ${mode==='execute'?'selected':''}>Conversar e executar</option><option value="plan" ${mode==='plan'?'selected':''}>Somente planejar</option></select></label><button type="submit" class="send-prompt" aria-label="Enviar pedido" ${submitting||active()||threadPending()?'disabled':''}>↑</button></div></div></form>${!data.messages.length?`<div class="conversation-suggestions"><button data-chat="suggest" data-text="Vamos estruturar o posicionamento e o plano de marketing da minha empresa."><span>✧</span>Planejar a semana</button><button data-chat="suggest" data-text="Quero criar uma campanha. Vamos definir objetivo, público, oferta e peças."><span>↗</span>Criar campanha</button><button data-chat="suggest" data-text="Quero criar uma imagem para minha marca. Use o contexto da empresa e as ferramentas disponíveis."><span>▧</span>Criar imagem</button><button data-chat="suggest" data-text="Quero produzir um vídeo para minha marca. Confira as ferramentas de vídeo disponíveis e me ajude a preparar o roteiro e a produção."><span>▷</span>Criar vídeo</button></div>`:''}${!s.integrations.some(i=>i.id==='openai'&&i.configured)?`<p class="conversation-connection-note"><a href="#/integrations">Conecte a inteligência</a> para receber respostas e executar pedidos.</p>`:''}</section>`;}
 function connectionLabel(p){return {disconnected:p.saved?'Perfil preservado · desconectado':'Não conectado',authentication_required:'Login necessário',identity_unconfirmed:'Identidade não confirmada',identity_confirmed:'Identidade confirmada',identity_declared:'Conta informada por você',uncertain:'Resultado incerto'}[p.connectionState]||(p.open?'Navegador aberto':p.saved?'Perfil preservado':'Não conectado');}
 function connectionIdentity(p){const identity=p.identity||p.validation?.identity;return `${identity?`<p class="session-identity">${esc(identity.username?'@'+identity.username.replace(/^@/,''):identity.accountLabel||p.accountLabel||'Identidade registrada')}${identity.accountId||identity.id?'<small>ID: '+esc(identity.accountId||identity.id)+'</small>':''}</p>`:''}${p.executorAvailable===false?'<p class="session-attention">O perfil permite login e conferência. Publicar por este navegador ainda não foi validado. Use uma API validada para executar a publicação.</p>':''}`;}
 function accounts(){ensureCompany();return `<section class="accounts-page"><div class="page-heading"><div><p class="overline">CONTAS CONECTADAS</p><h1>O seu navegador faz parte da equipe.</h1><p>Abra a sessão, faça login e confirme a identidade da conta desta empresa.</p></div><a class="p-button secondary" href="#/integrations">Conexões por API</a></div><div class="account-session-grid">${profiles.map(p=>`<article class="session-card"><div class="session-card-heading"><span class="service-monogram">${symbols[p.id]}</span><span class="session-state ${p.open?'is-open':''}">${esc(connectionLabel(p))}</span></div><h2>${esc(p.name)}</h2><p>${p.accountLabel?esc(p.accountLabel):'Sua conta, em uma sessão exclusiva desta empresa.'}</p>${connectionIdentity(p)}${p.uncertainNote?`<p class="session-attention">${esc(p.uncertainNote)}</p>`:''}${p.challenge?'<p class="session-attention">Conclua o login ou a confirmação no navegador.</p>':''}<small>${p.confirmedAt?'Conta confirmada por você · '+new Date(p.confirmedAt).toLocaleDateString('pt-BR'):'A abertura do navegador ainda não confirma o login.'}</small><div class="session-actions"><button class="p-button ${p.open?'secondary':'primary'}" data-chat="open-session" data-id="${p.id}">${p.open?'Abrir janela':'Conectar com login'}</button>${p.open?`<button class="p-button ghost" data-chat="confirm-session" data-id="${p.id}">Confirmar conta</button><button class="p-button ghost" data-chat="preview" data-id="${p.id}">Ver sessão</button>`:''}</div><label class="session-autonomy"><input type="checkbox" disabled ${p.automationAllowed&&p.executorAvailable!==false?'checked':''}>${p.executorAvailable===false?'Executor de publicação ainda não validado':p.automationAllowed?'Operação permitida nesta sessão':'Confirme a conta para permitir a operação'}</label></article>`).join('')||'<p class="padded">Carregando suas conexões…</p>'}</div>${preview?`<section class="browser-preview"><div><h2>${esc(profiles.find(p=>p.id===preview)?.name||'Navegador')} · sessão ao vivo</h2><button class="quiet-button" data-chat="hide-preview">Fechar prévia ×</button></div><img id="session-preview" src="${endpoint('browser/'+preview+'/preview')}?t=${Date.now()}" alt="Prévia da sessão conectada"><p>Para fazer login ou assumir o controle, use a janela aberta no seu computador. A prévia é ocultada durante a autenticação.</p></section>`:''}<div class="account-architecture-note"><h3>Uma inteligência. Mais de uma forma de trabalhar.</h3><p>A Helpu pode usar as APIs disponíveis e operar as sessões que você autorizar. Os perfis ficam neste computador, separados por empresa. Login e autenticação em duas etapas são feitos por você.</p><details><summary>Usar o Chrome que já está aberto</summary><p>O Chrome também oferece uma conexão supervisionada ao navegador existente. Esse caminho exige habilitar a depuração e aceitar a conexão no próprio Chrome. O adaptador para esse modo será separado das sessões dedicadas já disponíveis aqui.</p><a href="https://developer.chrome.com/blog/chrome-devtools-mcp-debug-your-browser-session" target="_blank" rel="noopener">Como funciona no Chrome ↗</a></details></div></section>`;}
 function paint(){if(!['conversation','browser'].includes(currentView))return;const prompt=$('#conversation-prompt'),focused=document.activeElement===prompt,position=prompt?.selectionStart;$('#workspace').innerHTML=currentView==='conversation'?chat():accounts();bind();if(focused){$('#conversation-prompt')?.focus();$('#conversation-prompt')?.setSelectionRange(position,position);}}
 async function load({repaint=true}={}){
  ensureCompany();const org=getState()?.company.id;if(!org)return;
  const requestedThread=thread,sequence=++loadSequence,base='/api/portal/'+org+'/';loading=true;
  const current=()=>sequence===loadSequence&&getState()?.company.id===org&&thread===requestedThread;
  try{
   const [ts,bs,next]=await Promise.all([api(base+'conversations'),api(base+'browser'),requestedThread?api(base+'conversations/'+requestedThread):Promise.resolve(null)]);
   if(!current())return;
   const profilesChanged=JSON.stringify(profiles)!==JSON.stringify(bs.profiles),threadsChanged=JSON.stringify(threads)!==JSON.stringify(ts.conversations),sig=next?JSON.stringify(next):'',changed=next&&sig!==signature;
   if(changed){await refresh(false);if(!current())return;}
   threads=ts.conversations;profiles=bs.profiles;
   if(next){data=next;signature=sig;loadedThread=requestedThread;}
   if(repaint&&(changed||profilesChanged||threadsChanged||!requestedThread))paint();
  }catch(e){if(current())toast(e.message,true);}finally{if(sequence===loadSequence)loading=false;}
 }
 function mount(view){currentView=view;if(!['conversation','browser'].includes(view))return;bind();load({repaint:true});if(!timer)timer=setInterval(()=>{if(document.hidden||!['conversation','browser'].includes(currentView))return;if(currentView==='browser'&&preview){const img=$('#session-preview');if(img)img.src=endpoint('browser/'+preview+'/preview')+'?t='+Date.now();}if(!submitting&&!loading)load({repaint:true});},3500);}
 function bind(){const prompt=$('#conversation-prompt');prompt?.addEventListener('input',e=>draft=e.target.value);$('#conversation-approved-media')?.addEventListener('change',e=>approvedMedia=e.target.checked);$('#conversation-mode')?.addEventListener('change',e=>mode=e.target.value);$('#conversation-composer')?.addEventListener('submit',send);$('#session-preview')?.addEventListener('error',e=>{e.target.alt='Prévia indisponível durante login, confirmação ou janela fechada. Use Abrir janela.';});}
 function send(e){e.preventDefault();if(submitting||active()||threadPending()||!draft.trim())return;try{validateAttachments(attachments);}catch(error){toast(error.message,true);return;}return submit();async function submit(){submitting=true;const selectedVersion=selectionVersion,org=getState().company.id,rawText=draft,text=draft+(approvedMedia&&approvedImage()?'\n\nA imagem anexada é a mídia aprovada para esta publicação.':''),sendMode=mode,sendAttachments=[...attachments],base='/api/portal/'+org+'/';try{if(!thread){const created=await api(base+'conversations','POST',{title:text.trim().slice(0,70)});if(getState()?.company.id!==org||selectedVersion!==selectionVersion)return;thread=created.id;}const currentThread=thread,fingerprint=JSON.stringify([org,currentThread,text,sendMode,sendAttachments]);if(pendingSubmission?.fingerprint!==fingerprint)pendingSubmission={fingerprint,key:crypto.randomUUID()};await api(base+'conversations/'+currentThread+'/messages','POST',{text,mode:sendMode,attachments:sendAttachments,idempotencyKey:pendingSubmission.key});if(getState()?.company.id!==org||thread!==currentThread||selectedVersion!==selectionVersion)return;pendingSubmission=null;if(draft===rawText){draft='';attachments=[];approvedMedia=false;}await load({repaint:false});paint();}catch(error){toast(error.message,true);}finally{submitting=false;paint();}}}
 function learnOperation(id){openDialog('Registrar aprendizado',`<form id="operation-learning-form"><p class="dialog-explainer">Registre uma observação fundamentada nas medições reais desta campanha. O aprendizado ficará em Marca e negócio, com suas fontes.</p><label class="p-field"><span>O que as medições mostram?</span><textarea name="note" required maxlength="12000" rows="4"></textarea></label><p class="form-error" role="alert" hidden></p><button type="submit" class="p-button primary">Salvar aprendizado</button></form>`);$('#operation-learning-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),error=form.querySelector('.form-error');button.disabled=true;error.hidden=true;try{await api(endpoint('operations/'+id+'/action'),'POST',{action:'learn',note:form.elements.note.value});await refresh(false);await load();closeDialog();toast('Aprendizado registrado com as fontes.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{button.disabled=false;}});}
 function history(){openDialog('Suas conversas',`<div class="chat-history-list">${threads.map(t=>`<button data-chat="choose-thread" data-id="${t.id}"><strong>${esc(t.title)}</strong><small>${new Date(t.updatedAt).toLocaleString('pt-BR')}</small></button>`).join('')||'<p>Sua primeira conversa começa com um objetivo.</p>'}</div>`);}
 function attachmentDialog(){const assets=getState().assets;openDialog('Adicionar uma referência',`<p class="dialog-explainer">Os arquivos ficam na biblioteca da sua empresa. A Helpu pode analisar as imagens e os PDFs anexados ao pedido. Vídeos entram como referências da biblioteca. Use até 20 MB de imagens e PDFs por mensagem.</p><div class="chat-history-list">${assets.map(a=>`<button data-chat="choose-attachment" data-id="${a.id}">${esc(a.name)}<small>${esc(a.mime)}</small></button>`).join('')||'<p>Nenhum arquivo na biblioteca.</p>'}</div><button class="p-button secondary" data-chat="upload-reference">Enviar arquivo</button><input id="conversation-file" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,application/pdf" hidden>`);$('#conversation-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const uploadOrg=getState().company.id,uploadThread=thread;try{if(attachments.length>=6)throw new Error('Adicione até seis referências por mensagem.');const total=attachments.reduce((n,id)=>{const a=getState().assets.find(a=>a.id===id);return n+(a&&(a.mime.startsWith('image/')||a.mime==='application/pdf')?a.size:0);},0);if((file.type.startsWith('image/')||file.type==='application/pdf')&&total+file.size>20*1024*1024)throw new Error('Use até 20 MB de imagens e PDFs por pedido.');if(file.size>25*1024*1024)throw new Error('Envie arquivos de até 25 MB.');const result=await uploadFile(endpoint('files'),file);if(getState().company.id!==uploadOrg||thread!==uploadThread)return;await refresh(false);if(getState().company.id!==uploadOrg||thread!==uploadThread)return;validateAttachments([...attachments,result.id]);attachments.push(result.id);approvedMedia=false;closeDialog();paint();}catch(error){toast(error.message,true);}});}
 function confirmSession(id){const p=profiles.find(x=>x.id===id);openDialog('Confirmar conta · '+p.name,`<form id="confirm-browser-form">${p.uncertainNote?`<div class="chat-run-error">${esc(p.uncertainNote)}</div><label class="checkline"><input name="reviewed" type="checkbox" required><span>Conferi o resultado da última ação diretamente na conta.</span></label>`:''}<p class="dialog-explainer">Confira a conta na janela do navegador. O login e os códigos são preenchidos diretamente no site.</p><label class="p-field"><span>Nome, @perfil ou telefone da conta aberta</span><input name="accountLabel" value="${esc(p.accountLabel)}" required maxlength="120"></label><label class="checkline"><input name="automationAllowed" type="checkbox" ${p.automationAllowed?'checked':''}><span>Permitir que a Helpu opere esta sessão para executar os meus pedidos.</span></label><p class="form-error" hidden></p><button type="submit" class="p-button primary">Confirmar esta conta</button></form>`);$('#confirm-browser-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('button'),error=f.querySelector('.form-error');button.disabled=true;try{await api(endpoint('browser/'+id+'/confirm'),'POST',{accountLabel:f.elements.accountLabel.value,automationAllowed:f.elements.automationAllowed.checked,reviewed:f.elements.reviewed?.checked===true});closeDialog();await load();toast('Conta confirmada na sua empresa.');}catch(err){error.textContent=err.message;error.hidden=false;}finally{button.disabled=false;}});}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-chat]');if(!b)return;const a=b.dataset.chat,id=b.dataset.id;try{
  if(a==='suggest'){draft=b.dataset.text;paint();$('#conversation-prompt')?.focus();}
  else if(a==='new'){clearThread();paint();}
  else if(a==='history')history();else if(a==='choose-thread'){clearThread(id);closeDialog();paint();await load();}
  else if(a==='attach')attachmentDialog();else if(a==='choose-attachment'){if(attachments.length>=6)throw new Error('Adicione até seis referências por mensagem.');if(!attachments.includes(id)){validateAttachments([...attachments,id]);attachments.push(id);approvedMedia=false;}closeDialog();paint();}else if(a==='remove-attachment'){attachments=attachments.filter(x=>x!==id);approvedMedia=false;paint();}else if(a==='upload-reference')$('#conversation-file').click();
  else if(a==='operation-action'){if(b.dataset.operationAction==='learn'){learnOperation(id);return;}b.disabled=true;await api(endpoint('operations/'+id+'/action'),'POST',{action:b.dataset.operationAction});await refresh(false);await load();toast('Operação atualizada.');}
  else if(a==='stop'){await api(endpoint('conversations/'+thread+'/stop'),'POST',{});toast('Pausa solicitada. A etapa em andamento será registrada.');}
  else if(a==='open-session'){b.disabled=true;await api(endpoint('browser/'+id+'/open'),'POST',{});await load();toast('Faça login na janela do navegador e confirme a conta.');}
  else if(a==='confirm-session')confirmSession(id);else if(a==='preview'){preview=id;paint();}else if(a==='hide-preview'){preview='';paint();}
 }catch(error){toast(error.message,true);}finally{b.disabled=false;}});
 return {chat,accounts,mount,reload:()=>load(),async selectThread(id){ensureCompany();clearThread(id);paint();await load();},reset(){companyId='';clearThread();threads=[];profiles=[];preview='';}};
}
